function validate([n, logs]) {
  if (!Number.isInteger(n) || n < 1 || n > 100) return 'n is between 1 and 100.';
  if (!Array.isArray(logs) || logs.length < 2 || logs.length > 500) return 'logs needs 2 to 500 entries.';
  const stack = [];
  let prevPos = -1, prevType = '';
  for (const log of logs) {
    const match = /^(0|[1-9]\d*):(start|end):(0|[1-9]\d*)$/.exec(log);
    if (!match) return 'Each log looks like "id:start:time" or "id:end:time".';
    const id = Number(match[1]), type = match[2], time = Number(match[3]);
    if (id >= n) return 'Function ids are between 0 and n - 1.';
    if (time > 1e9) return 'Timestamps are between 0 and 10^9.';
    // A start begins its unit and an end finishes its unit, so compare the moments they mark.
    const moment = type === 'start' ? time : time + 1;
    if (moment < prevPos || (moment === prevPos && !(type === 'start' && prevType === 'end'))) return 'Logs must be in time order, with no two starts or two ends at the same timestamp.';
    if (type === 'start') stack.push(id);
    else if (stack.length === 0 || stack.pop() !== id) return 'Each end must close the most recent unfinished call of the same function.';
    prevPos = moment;
    prevType = type;
  }
  if (stack.length > 0) return 'Every start needs a matching end.';
  return null;
}

