function exclusiveTime(n, logs) {
  const events = logs.map(log => {
    const parts = log.split(':');
    return { id: +parts[0], start: parts[1] === 'start', time: +parts[2] };
  });
  // Pair each start with its end by scanning forward with a depth counter.
  const calls = [];
  for (let i = 0; i < events.length; i++) {
    if (!events[i].start) continue;
    let depth = 0;
    for (let j = i + 1; j < events.length; j++) {
      if (events[j].start) depth++;
      else if (depth === 0) { calls.push({ id: events[i].id, from: events[i].time, to: events[j].time }); break; }
      else depth--;
    }
  }
  // Between consecutive boundaries the same call runs: the innermost (latest-starting) call covering that unit.
  const cuts = [...new Set(calls.flatMap(c => [c.from, c.to + 1]))].sort((a, b) => a - b);
  const total = new Array(n).fill(0);
  for (let k = 0; k + 1 < cuts.length; k++) {
    const unit = cuts[k];
    let owner = null;
    for (const c of calls) if (c.from <= unit && unit <= c.to && (owner === null || c.from > owner.from)) owner = c;
    if (owner) total[owner.id] += cuts[k + 1] - cuts[k];
  }
  return total;
}

