function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 3);
  const callCount = size === 'large' ? 250 : 1 + Math.floor(rand() * 6);
  const spread = size === 'large' ? (rand() < 0.5 ? 1000000 : 3) : 3;
  const gap = () => Math.floor(rand() * (spread + 1));
  const logs = [], stack = [];
  let pos = Math.floor(rand() * 5), last = 'none', started = 0;
  while (started < callCount || stack.length > 0) {
    const canStart = started < callCount;
    if (canStart && (stack.length === 0 || rand() < 0.5)) {
      const time = pos + gap() + (last === 'start' ? 1 : 0);
      const id = Math.floor(rand() * n);
      logs.push(`${id}:start:${time}`);
      stack.push(id);
      started++;
      pos = time;
      last = 'start';
    } else {
      const time = pos + gap();
      logs.push(`${stack.pop()}:end:${time}`);
      pos = time + 1;
      last = 'end';
    }
  }
  return [n, logs];
}
